use super::*;

/// How long the money lasts — on the LOW band, and saying so.
///
/// The headline is deliberately the pessimistic scenario. A runway on expected income is right on
/// average and useless in the case that matters, so the other two are shown as context BENEATH it
/// rather than offered as alternatives to quote.
pub fn render_runway(r: &runway::Runway, p: &projection::IncomeProjection, c: &obligations::ObligationCalendar, notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);

    if r.headline.months.is_empty() {
        out.push_str(&format!("{}\n", runway::summarise(r)));
        for x in &r.problems {
            out.push_str(&format!("  · {x}\n"));
        }
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }

    out.push_str(&format!("{}\n\n", runway::summarise(r)));
    out.push_str(&format!("  starting liquid  {}\n\n", m(r.starting_liquid.minor)));
    out.push_str("  month      opening       income   obligations   discretionary       closing\n");
    for x in &r.headline.months {
        out.push_str(&format!(
            "  {:<9}{:>11}  {:>11}   {:>11}     {:>11}   {:>11}{}\n",
            x.month,
            m(x.opening.minor),
            m(x.income.minor),
            m(x.obligations.minor),
            m(x.discretionary.minor),
            m(x.closing.minor),
            if x.shortfall.is_some() { "  SHORT" } else { "" },
        ));
    }

    if !runway::survives_horizon(&r.headline) {
        out.push_str(&format!(
            "\n  {} a month more closes it — {} over a year\n",
            m(r.headline.monthly_gap.minor),
            m(runway::annual_gap(r).minor)
        ));
    }
    // The other two scenarios are CONTEXT, shown as the gap each would need rather than as a length
    // of runway — a reader who sees "expected: 11 months" will quote that number.
    out.push_str(&format!(
        "\n  if income comes in at expected  {} a month short · at high  {} a month short\n",
        m(r.expected.monthly_gap.minor),
        m(r.high.monthly_gap.minor)
    ));

    if let Some(h) = obligations::heaviest_window(c, 7) {
        out.push_str(&format!("\n  heaviest week  {} → {}  {}\n", h.from, h.to, m(h.total.minor)));
    }

    out.push_str("\nWhat this is standing on:\n");
    for a in &p.assumptions {
        out.push_str(&format!("  · {a}\n"));
    }
    for x in &r.problems {
        out.push_str(&format!("  · {x}\n"));
    }
    for x in &c.notes {
        out.push_str(&format!("  · {x}\n"));
    }
    for n in notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
